-- FBG Assessment Dummy Data
-- Populates fbg_assessments with 90 realistic, varied records across 5
-- hospitals so the FBG dashboard has something meaningful to show.
-- Also seeds those 5 hospitals (INSERT IGNORE) since the assessments'
-- hospital_id foreign key needs them to exist -- harmless if you already
-- have hospitals with different codes.
--
-- Requires: mysql/001_schema.sql, mysql/002_seed.sql, fbg_schema.sql
-- already loaded. Safe to re-run (fbg_assessments rows get fresh ids
-- each run, so re-running adds another batch rather than duplicating).

SET NAMES utf8mb4;


